import dayjs from 'dayjs';
/**
 * 通过 format 来格式化日期，因为支持了function 所以需要单独的方法来处理
 * @param  {any} endText
 * @param  {FormatType} format
 * @return string
 */
const toDayjsInstance = endText => {
  if (dayjs.isDayjs(endText)) {
    return endText;
  }
  if (endText != null && typeof endText.format === 'function' && typeof endText.isValid === 'function') {
    return endText;
  }
  return dayjs(endText);
};
const formatString = (endText, format) => {
  const d = toDayjsInstance(endText);
  if (typeof format === 'function') {
    return format(d);
  }
  return d.format(format);
};
/**
 * 格式化区域日期,如果是一个数组，会返回 start ~ end
 * @param  {any} value
 * @param  {FormatType | FormatType[]} format
 * returns string
 */
export const dateArrayFormatter = (value, format) => {
  const [startText, endText] = Array.isArray(value) ? value : [];
  let formatFirst;
  let formatEnd;
  if (Array.isArray(format)) {
    formatFirst = format[0];
    formatEnd = format[1];
  } else if (typeof format === 'object' && format.type === 'mask') {
    formatFirst = format.format;
    formatEnd = format.format;
  } else {
    formatFirst = format;
    formatEnd = format;
  }

  // activePickerIndex for https://github.com/ant-design/ant-design/issues/22158
  const parsedStartText = startText ? formatString(startText, formatFirst) : '';
  const parsedEndText = endText ? formatString(endText, formatEnd) : '';
  const valueStr = parsedStartText && parsedEndText ? `${parsedStartText} ~ ${parsedEndText}` : '';
  return valueStr;
};